class Solution { bool adjacent(string& a,string& b){if(a.size()!=b.size())return false;int differences=0;for(int i=0;i<(int)a.size();++i)if(a[i]!=b[i]&&++differences>1)return false;return differences==1;}public:vector<string> getWordsInLongestSubsequence(vector<string>& words,vector<int>& groups){int n=words.size();vector<int> dp(n,1),previous(n,-1);int best=0;for(int i=0;i<n;++i){for(int j=0;j<i;++j)if(groups[i]!=groups[j]&&adjacent(words[i],words[j])&&dp[j]+1>dp[i]){dp[i]=dp[j]+1;previous[i]=j;}if(dp[i]>dp[best])best=i;}vector<string> answer;for(int node=best;node!=-1;node=previous[node])answer.push_back(words[node]);reverse(answer.begin(),answer.end());return answer;} };
